<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, toRef, watch } from 'vue';
import { NAlert, NButton, NCard, NCollapse, NCollapseItem, NFormItem, NInput, NInputNumber, NModal, NSelect, NSpace, NSwitch, NTag, useDialog, useMessage } from 'naive-ui';
import { Download, Activity, Eraser } from '@vicons/tabler';
import { native, request, hostRoot } from '../api';
import { useRuntime } from '../stores/runtime';
import { useResource } from '../composables';
import ResourceState from '../components/ResourceState.vue';
const runtime=useRuntime();const message=useMessage();const dialog=useDialog();const busy=ref(false);const profileName=ref('');
const edits=reactive<Record<string,any>>({});const jsonDrafts=reactive<Record<string,string>>({});const jsonErrors=reactive<Record<string,string>>({});const soul=ref('');const savedSoul=ref('');
const rawModal=ref(false);const rawBusy=ref(false);const rawYaml=ref('');const rawPath=ref('');
// ── 应用更新（从概览页移入设置页）：核心与适配层始终作为同一个 FPK 发布 ──
const checking=ref(false);const release=ref<any>(null);
// 「获取 FPK」走宿主同源下载端点（服务端代下：ghproxy 中继→GitHub 直连，流式 + Content-Disposition），
// 浏览器原生下载器接管 → 显示进度、不被 webview 跨站拦截（旧版直链 github.com target=_blank 在飞牛面板卡死）。
const fpkDownloadUrl=computed(()=>{try{return new URL('api/host/update/download',hostRoot).href;}catch{return '';}});
async function checkUpdate(){checking.value=true;try{release.value=await request('api/host/update/check');message.success(release.value.core?.updateAvailable||release.value.app?.updateAvailable?'发现可用更新':'当前已是最新稳定版');}catch(e){message.error((e as Error).message);}finally{checking.value=false;}}
// ── GitHub PAT（落盘 0600，查 Release 时带 Bearer 绕过未认证限流）──
const patDraft=ref('');const patBusy=ref(false);
const patState=computed(()=>({hasPat:!!release.value?.github?.hasPat,source:String(release.value?.github?.source||'none')}));
async function savePat(){patBusy.value=true;const was=patDraft.value.trim();try{await request('api/host/update/token',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pat:was})});message.success(was?'GitHub PAT 已保存（0600 存于变量目录）':'GitHub PAT 已清除');patDraft.value='';try{release.value=await request('api/host/update/check');}catch{}}catch(e){message.error(`GitHub PAT ${was?'保存':'清除'}失败：${(e as Error).message}`);}finally{patBusy.value=false;}}
// ── 维护与恢复（真实接入 hermes 核心能力：doctor 诊断 + 白名单日志清理；非占位文案）──
const maintBusy=ref(false);const doctorResult=ref<any>(null);const doctorExpanded=ref(false);const clearFile=ref('hermes.log');const logFiles=ref<string[]>(['hermes.log','gateway.log','agent.log','errors.log','gui.log']);
async function runDoctor(live:boolean){maintBusy.value=true;try{const result:any=await request('api/host/maintenance/doctor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({live})});doctorResult.value=result;}catch(e){doctorResult.value={ok:false,error:(e as Error).message};}finally{maintBusy.value=false;}}
async function clearLog(file:string){try{await request('api/host/maintenance/logs/clear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file})});message.success(`日志 ${file} 已清空`);}catch(e){message.error((e as Error).message);}}
const {data,loading,error,refresh}=useResource(async()=>{
  const owner=runtime.profile;
  const [config,schema,role]=await Promise.all([native('/api/config',owner),native('/api/config/schema',owner),native(`/api/profiles/${encodeURIComponent(owner)}/soul`,owner)]);
  return {config,schema,role,owner};
},[toRef(runtime,'profile')]);
watch(data,value=>{Object.keys(edits).forEach(k=>delete edits[k]);Object.keys(jsonDrafts).forEach(k=>delete jsonDrafts[k]);Object.keys(jsonErrors).forEach(k=>delete jsonErrors[k]);soul.value=value?.role.content||'';savedSoul.value=soul.value;});
const dirty=computed(()=>Object.keys(edits).length>0||soul.value!==savedSoul.value);
watch(dirty,value=>{runtime.unsaved=value;});
const preventUnload=(event:BeforeUnloadEvent)=>{if(dirty.value){event.preventDefault();event.returnValue='';}};
window.addEventListener('beforeunload',preventUnload);
onBeforeUnmount(()=>{runtime.unsaved=false;window.removeEventListener('beforeunload',preventUnload);});
const get=(object:any,key:string)=>key.split('.').reduce((v,k)=>v?.[k],object);
const coreGroups=[{id:'compression',name:'上下文与压缩',categories:['compression']},{id:'memory',name:'原生记忆',categories:['memory']},{id:'security',name:'执行、审批与安全',categories:['security','approvals']},{id:'voice',name:'语音、听写与朗读',categories:['voice','tts','stt']}];
const categoryLabels:Record<string,string>={general:'通用',agent:'Agent 行为',models:'模型与路由',model:'模型与路由',tools:'工具',skills:'技能',mcp:'MCP',browser:'浏览器',terminal:'终端',sessions:'会话',gateway:'通讯网关',messaging:'通讯',cron:'定时任务',observability:'可观测性',updates:'更新',plugins:'插件',files:'文件',sandbox:'沙箱',delegation:'委派与子代理'};
const groups=computed(()=>{const claimed=new Set(coreGroups.flatMap(group=>group.categories));const categories=new Set<string>();for(const field of Object.values<any>(data.value?.schema.fields||{})){if(field.category&&!claimed.has(field.category))categories.add(field.category);}return [...coreGroups,...[...categories].sort().map(category=>({id:`native-${category}`,name:categoryLabels[category]||`原生设置 · ${category}`,categories:[category]}))];});
const labels:Record<string,string>={'compression.enabled':'启用上下文压缩','compression.threshold':'压缩触发比例','compression.target_ratio':'压缩目标比例','compression.protect_last_n':'保护最近消息数','memory.memory_enabled':'启用长期记忆','memory.user_profile_enabled':'启用用户偏好记忆','memory.memory_char_limit':'长期记忆字符上限','memory.user_char_limit':'用户偏好字符上限'};
function fields(categories:string[]) {
  return Object.entries<any>(data.value?.schema.fields||{}).filter(([key,field])=>categories.includes(field.category)&&!/(api_key|secret|token|password)/i.test(key)).map(([key,field])=>({key,...field}));
}
function value(key:string){return key in edits?edits[key]:get(data.value?.config,key);}
function edit(key:string,next:any){if(next===get(data.value?.config,key))delete edits[key];else edits[key]=next;}
function jsonValue(key:string){if(!(key in jsonDrafts))jsonDrafts[key]=JSON.stringify(value(key)??(Array.isArray(value(key))?[]:{}),null,2);return jsonDrafts[key];}
function editJson(key:string,next:string){jsonDrafts[key]=next;try{const parsed=JSON.parse(next);delete jsonErrors[key];edit(key,parsed);}catch{jsonErrors[key]='JSON 格式无效';delete edits[key];}}
function cancel(){Object.keys(edits).forEach(k=>delete edits[k]);Object.keys(jsonDrafts).forEach(k=>delete jsonDrafts[k]);Object.keys(jsonErrors).forEach(k=>delete jsonErrors[k]);soul.value=savedSoul.value;}
function promptRestart(){dialog.warning({title:'设置已保存',content:'Hermes 需要重启后才能完整应用本次配置。正在进行的对话会中断。',positiveText:'立即重启 Hermes',negativeText:'稍后重启',onPositiveClick:async()=>{try{await runtime.service('restart');message.success('Hermes 已提交重启');}catch(e){message.error((e as Error).message);}}});}
async function save(){
  if(!data.value||loading.value||error.value)return;
  if(Object.keys(jsonErrors).length)return message.error('请先修正无效的 JSON 参数');
  const owner=data.value.owner;const patch:Record<string,any>={};
  for(const [key,next]of Object.entries(edits)){
    if(next===null||next===undefined)return message.error('已编辑的参数不能为空，请填写或取消修改');
    const parts=key.split('.');let node=patch;parts.forEach((part,index)=>{if(index===parts.length-1)node[part]=next;else node=node[part]??={};});
  }
  busy.value=true;
  try{
    if(Object.keys(patch).length)await native('/api/config',owner,'PUT',{config:patch});
    if(soul.value!==savedSoul.value)await native(`/api/profiles/${encodeURIComponent(owner)}/soul`,owner,'PUT',{content:soul.value});
    if(owner===runtime.profile)await refresh();
    promptRestart();
  }catch(e){message.error((e as Error).message);}finally{busy.value=false;}
}
async function createProfile(){const name=profileName.value.trim();if(!name)return;busy.value=true;try{await native('/api/profiles',runtime.profile,'POST',{name,clone_from_default:false,no_skills:true});await runtime.refresh();runtime.profile=name;profileName.value='';message.success('已创建独立 Profile');}catch(e){message.error((e as Error).message);}finally{busy.value=false;}}
function deleteProfile(name:string){if(name==='default')return;dialog.warning({title:`删除 Profile “${name}”？`,content:'该 Profile 的配置、会话、记忆与专属凭据将被删除。此操作不能在 Admin 中撤销。',positiveText:'删除 Profile',negativeText:'取消',onPositiveClick:async()=>{busy.value=true;try{await native(`/api/profiles/${encodeURIComponent(name)}`,runtime.profile,'DELETE');if(runtime.profile===name)runtime.profile='default';await runtime.refresh();message.success(`Profile “${name}”已删除`);}catch(e){message.error((e as Error).message);}finally{busy.value=false;}}});}
async function openRawConfig(){if(dirty.value)return message.warning('请先保存或取消当前表单修改');rawBusy.value=true;try{const result:any=await native('/api/config/raw',runtime.profile);rawYaml.value=result.yaml||'';rawPath.value=result.path||'';rawModal.value=true;}catch(e){message.error((e as Error).message);}finally{rawBusy.value=false;}}
async function saveRawConfig(){rawBusy.value=true;try{await native('/api/config/raw',runtime.profile,'PUT',{yaml_text:rawYaml.value,profile:runtime.profile});rawModal.value=false;await refresh();promptRestart();}catch(e){message.error((e as Error).message);}finally{rawBusy.value=false;}}
</script>
<template>
  <div class="toolbar"><span class="muted">正在编辑 <b>{{ runtime.profile }}</b></span><n-space><n-button :disabled="!dirty||busy" @click="cancel">取消修改</n-button><n-button type="primary" :disabled="!dirty||loading||!!error" :loading="busy" @click="save">保存设置</n-button></n-space></div>
  <n-card title="Profile" :bordered="false" class="mb"><p class="muted mb">不同 Profile 使用独立的 Hermes 配置与数据。切换 Profile 不改变飞牛登录账号。</p><div class="inline mb"><n-input v-model:value="profileName" placeholder="新 Profile 名称" style="max-width:320px" /><n-button :loading="busy" :disabled="!profileName.trim()||dirty" @click="createProfile">创建 Profile</n-button></div><div class="profile-list"><div v-for="item in runtime.profiles" :key="item.name" class="profile-row"><div><strong>{{ item.display_name||item.name }}</strong><span class="muted">{{ item.name }}</span></div><n-space><n-tag v-if="item.name===runtime.profile" type="success" size="small" :bordered="false">当前</n-tag><n-button v-if="item.name!=='default'" size="small" type="error" secondary :disabled="busy||dirty" @click="deleteProfile(item.name)">删除</n-button><n-tag v-else size="small" :bordered="false">内置</n-tag></n-space></div></div></n-card>
  <ResourceState :loading="loading" :error="error" @retry="refresh">
    <n-card :bordered="false" class="mb"><template #header>高级设置</template><template #header-extra><n-button size="small" :loading="rawBusy" :disabled="dirty" @click="openRawConfig">打开配置文件</n-button></template><p class="muted mb">使用当前 Hermes 版本的原生参数；未修改的字段会保留。保存后需要重启 Hermes。</p><n-collapse>
      <n-collapse-item title="角色提示词" name="soul"><p class="muted mb">当前 Profile 的 SOUL.md。已有工作区 AGENTS 内容保持原有归属。</p><n-input v-model:value="soul" type="textarea" :autosize="{minRows:7,maxRows:18}" placeholder="尚未设置角色提示词" /></n-collapse-item>
      <n-collapse-item v-for="group in groups" :key="group.id" :title="`${group.name}（${fields(group.categories).length}）`" :name="group.id"><div class="settings-fields"><n-form-item v-for="field in fields(group.categories)" :key="field.key" :label="labels[field.key]||field.description||field.key" :validation-status="jsonErrors[field.key]?'error':undefined" :feedback="jsonErrors[field.key]"><div class="field-value"><n-switch v-if="field.type==='boolean'||typeof value(field.key)==='boolean'" :value="!!value(field.key)" @update:value="next=>edit(field.key,next)" /><n-select v-else-if="field.type==='select'||field.options?.length" :value="value(field.key)" :options="(field.options||[]).map((o:any)=>typeof o==='object'?o:{label:o||'默认',value:o})" @update:value="next=>edit(field.key,next)" /><n-input-number v-else-if="field.type==='number'||typeof value(field.key)==='number'" :value="value(field.key)" @update:value="next=>edit(field.key,next)" /><n-input v-else-if="Array.isArray(value(field.key))||typeof value(field.key)==='object'" type="textarea" :autosize="{minRows:3,maxRows:10}" :value="jsonValue(field.key)" @update:value="next=>editJson(field.key,next)" /><n-input v-else :value="value(field.key)==null?'':String(value(field.key))" @update:value="next=>edit(field.key,next)" /><small>{{ field.key }}</small></div></n-form-item></div><p v-if="!fields(group.categories).length" class="muted">当前版本未提供可编辑的参数。</p></n-collapse-item>
    </n-collapse></n-card>
  </ResourceState>
  <n-card title="维护与恢复" :bordered="false" class="mb"><p class="muted mb">接入 Hermes 核心维护能力：doctor 诊断会检查配置与依赖（--fix 自动修复，--live 追加对工具后端的只读真实网络探针），日志清理仅限白名单 8 个文件。完整备份 / 恢复 / 依赖重装随 FPK 升级与飞牛应用中心完成，本页不执行这些破坏性操作。</p><n-space class="mb"><n-button :loading="maintBusy" @click="runDoctor(false)"><template #icon><n-icon :component="Activity"/></template>运行诊断（hermes doctor）</n-button><n-button :loading="maintBusy" @click="runDoctor(true)"><template #icon><n-icon :component="Activity"/></template>诊断 + 网络探针（--live）</n-button></n-space><n-alert v-if="doctorResult" :type="doctorResult.ok?'success':'error'" :bordered="false" class="mb"><div style="font-size:12px;line-height:1.7;white-space:pre-wrap;font-family:Consolas,monospace">{{ doctorResult.error||(doctorResult.summary||'诊断完成') }}</div><div v-if="doctorResult.command" class="muted mt" style="font-size:11px">命令：{{ doctorResult.command }} · 退出码 {{ doctorResult.exitCode }}<span v-if="doctorResult.durationMs!=null"> · 耗时 {{ (doctorResult.durationMs/1000).toFixed(1) }}s</span></div><n-button v-if="(doctorResult.lines||[]).length>8" text type="primary" size="tiny" @click="doctorExpanded=!doctorExpanded">{{ doctorExpanded?'收起完整输出':'查看完整输出' }}</n-button><div v-if="doctorExpanded" class="muted mt" style="font-size:11px;line-height:1.6;white-space:pre-wrap;font-family:Consolas,monospace;max-height:220px;overflow:auto">{{ (doctorResult.lines||[]).join('\n') }}</div></n-alert><n-collapse><n-collapse-item title="清空日志（白名单 8 文件）" name="clearlog"><div class="muted mb">截断为 0 字节，不影响运行中进程。可选文件：</div><div class="inline mb"><n-select v-model:value="clearFile" :options="logFiles.map(f=>({label:f,value:f}))" style="width:200px" /><n-button :disabled="!clearFile" @click="clearLog(clearFile)"><template #icon><n-icon :component="Eraser"/></template>清空</n-button></div></n-collapse-item></n-collapse></n-card>
  <n-card title="应用更新" :bordered="false" class="mb"><div class="split"><div class="resource-description"><h3>完整 FPK 更新</h3><p>核心与适配层始终作为同一个 FPK 发布。升级时由飞牛应用中心覆盖安装，保留 Profile、会话、凭据和工作区数据，避免核心与适配层版本混装。</p><div v-if="release" class="mt"><n-tag :type="release.core?.updateAvailable?'warning':'success'" :bordered="false">Hermes {{ release.core?.current }} → {{ release.core?.latest }}</n-tag><span class="muted" style="margin-left:10px">应用 {{ release.app?.current }}{{ release.app?.latest?` → ${release.app.latest}`:'' }}</span></div><n-collapse v-if="release?.app?.body" :default-expanded="[]" class="mt" size="small"><n-collapse-item title="更新说明" name="notes"><pre class="muted" style="margin:0;font-size:11px;line-height:1.6;white-space:pre-wrap">{{ release.app.body }}</pre></n-collapse-item></n-collapse></div><n-space vertical><n-space><n-button :loading="checking" @click="checkUpdate">检查更新</n-button><n-button v-if="release?.app?.downloadUrl||release?.app?.releaseUrl" type="primary" tag="a" :href="fpkDownloadUrl" download><template #icon><n-icon :component="Download"/></template>获取 FPK</n-button></n-space><div class="muted" style="font-size:11px">检查更新需要访问 GitHub Release。{{ release?.github?.hasPat ? `当前使用已保存的 PAT（${release.github.source==='env'?'环境变量':'落盘'}），不受未认证限流。` : '未配置 PAT 时走未认证通道（60 次/小时限流，够用但偶尔会撞墙）。' }}</div><n-space v-if="release?.github?.hasPat||patDraft" size="small"><n-input v-model:value="patDraft" :show="!patState.hasPat" type="password" placeholder="GitHub Personal Access Token（可留空，保存留空即清除）" style="width:300px" :disabled="patBusy" /><n-button :loading="patBusy" @click="savePat">{{ patState.hasPat?'更新 / 清除':'保存 PAT' }}</n-button></n-space></n-space></div></n-card>
  <n-card title="关于" :bordered="false"><div class="about-grid"><span>Hermes 核心</span><b>{{ runtime.version?.version||runtime.version?.tag||'—' }}</b><span>更新方式</span><span>飞牛应用中心整包升级（FNS_FPK）</span><span>数据目录</span><code>{{ runtime.status?.dataRoot||'—' }}</code><span>运行环境</span><span>飞牛 NAS（hermes-agent FPK）</span></div></n-card>
  <n-modal v-model:show="rawModal" preset="card" title="配置文件" style="width:820px;max-width:calc(100vw - 32px)"><n-alert type="warning" :bordered="false" class="mb">这是当前 Profile 的原始 YAML。无效内容会被 Hermes 拒绝；保存后需要重启 Hermes。</n-alert><n-form-item label="文件路径"><n-input :value="rawPath" readonly /></n-form-item><n-form-item label="config.yaml"><n-input v-model:value="rawYaml" type="textarea" :autosize="{minRows:18,maxRows:28}" class="raw-config-editor" /></n-form-item><template #footer><div class="modal-footer"><n-button @click="rawModal=false">取消</n-button><n-button type="primary" :loading="rawBusy" @click="saveRawConfig">保存配置文件</n-button></div></template></n-modal>
</template>
